# LangGraph in Depth: tiny workflow transition.
state = {"ticket": "refund missing invoice", "evidence": [], "risk": "low", "draft": None}

def next_node(state):
    if not state["evidence"]:
        return "retrieve"
    if state["risk"] == "high":
        return "human_review"
    return "draft"

print(next_node(state))
state["evidence"].append("refund policy: invoice id required")
print(next_node(state))

